The strategy of the proof is the following: First we assume $\gamma$ to be an orbitlike elastica in~$\mathbb{H}$ parametrized by hyperbolic arclength and derive the formulas \eqref{eq:explicit_formula_orbitlike_1}--\eqref{eq:b3a3_2}. This will prove the ''only if''-part of our claim. Then we check that the formulas \eqref{eq:explicit_formula_orbitlike_1}--\eqref{eq:a_1a_2a_3b_1b_2b_3} indeed define orbitlike elasticae which, as solutions of \eqref{eq:ODE_kappa}, are parametrized by hyperbolic arclength. \medskip So let us first assume that $\gamma$ is an orbitlike elastica in $\mathbb{H}$ so that identity \eqref{eq:formula_Z} holds for all $s,s_0\in\mathbb{R}$ by Proposition~ef{prop:formula_Z_orbitlike}. We multiply \eqref{eq:formula_Z} with $2P_2\gamma_2(s)$ and obtain  egin{align*} (\gamma_1(s)-P_1)^2+\gamma_2(s)^2+P_2^2 = 2\gamma_2(s)\kappa(s)P_2 ig( A W_1(s) + B W_2(s) + C  ig) \end{align*} where $A,B,C$ are given by the formulas \eqref{eq:formula_AB},\eqref{eq:def_C}. Equating the coefficients of the monomial $P_2^2$ we get  egin{align*} 1 &=  rac{\gamma_2(s)\kappa(s)}{\gamma_2(s_0)} \Big( \xi^1(s_0)_1 W_1(s) + \xi^1(s_0)_2 W_2(s) \ &\quad +  rac{\kappa(s_0)}{\mu}+ rac{\kappa'(s_0)}{\mu}\sin(\phi(s_0)) -  rac{\kappa(s_0)^2}{2\mu}\cos(\phi(s_0))\Big) \ &= \gamma_2(s)\kappa(s) ig(a_1 W_1(s)+a_2W_2(s)+a_3 ig) \end{align*} and thus \eqref{eq:explicit_formula_orbitlike_2} is proved. Notice that the above identity holds for all $s_0\in\mathbb{R}$, which proves the formulas \eqref{eq:a1a2b1b2_1},\eqref{eq:b3a3_2} for $a_1,a_2,a_3$. Similarly, equating the coefficients of $P_1$ we get  egin{align*} -2\gamma_1(s) &=  rac{2\gamma_2(s)\kappa(s)}{\gamma_2(s_0)} \Big( -  ig(\gamma_1(s_0)\xi^1(s_0)+\gamma_2(s_0)\xi^3(s_0) ig)_1 W_1(s) \ &- ig(\gamma_1(s_0)\xi^1(s_0)+\gamma_2(s_0)\xi^3(s_0) ig)_2 W_2(s) \ &- \gamma_1(s_0) \Big( rac{\kappa(s_0)}{\mu}+ rac{\kappa'(s_0)}{\mu}\sin(\phi(s_0)) -  rac{\kappa(s_0)^2}{2\mu}\cos(\phi(s_0))\Big) \ &-\gamma_2(s_0)\Big(- rac{\kappa(s_0)^2}{2\mu}\sin(\phi(s_0))- rac{\kappa'(s_0)}{\mu}\cos(\phi(s_0))\Big) \Big) \ &= -2\gamma_2(s)\kappa(s) ig(b_1W_1(s)+b_2W_2(s)+b_3 ig). \end{align*} In the same way as above this implies the formulas \eqref{eq:explicit_formula_orbitlike_1},\eqref{eq:a1a2b1b2_2},\eqref{eq:b3a3_1} involving $b_1,b_2,b_3$. It therefore remains to prove \eqref{eq:a_1a_2a_3b_1b_2b_3} to finish the ''only if''-part. To this end we introduce the matrices  egin{align*} \mathcal{W}:=\matII{W_1}{W_2}{W_1'}{W_2'},\qquad \mathcal{R}(\vartheta):=\matII{\cos(\vartheta)}{\sin(\vartheta)}{-\sin(\vartheta)}{\cos(\vartheta)}. \end{align*} Then Proposition~ef{prop:properties_vartheta_orbitlike} gives the following:  egin{align*} \mathcal{W} &= \matII{0}{ rac{\sqrt{\kappa^2-\mu}}{\kappa}}{ rac{-\sqrt{\mu}\kappa}{2\sqrt{\kappa^2-\mu}}}{  rac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}} \mathcal{R}(\vartheta),\qquad \mathcal{W}^{-1} = \mathcal{R}(-\vartheta) \matII{ rac{2\sqrt{\mu}\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}{- rac{2\sqrt{\kappa^2-\mu}}{\sqrt{\mu}\kappa}} { rac{\kappa}{\sqrt{\kappa^2-\mu}}}{0}. \ \intertext{Combining this with \eqref{eq:formula_xi} and $(\kappa')^2=\kappa^2- rac{1}{4}\kappa^4-\mu$ we get} \xi^1 &= \mathcal{R}(-\vartheta) \vecII{ rac{1}{2\sqrt{\mu(\kappa^2-\mu)}}(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))}{  rac{1}{2\mu\sqrt{\kappa^2-\mu}}(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi)) }, \ \xi^3 &= \mathcal{R}(-\vartheta) \vecII{ rac{1}{2\sqrt{\mu(\kappa^2-\mu)}}(2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{  rac{\kappa}{2\mu\sqrt{\kappa^2-\mu}}(\kappa^2\sin(\phi)+2\kappa'\cos(\phi)) }. \end{align*} Writing $\skp{\cdot}{\cdot}$ for the standard inner product in $\mathbb{R}^2$ we get from $(\kappa')^2=\kappa^2- rac{\kappa^4}{4}-\mu$ and the fact that the rotation matrices $\mathcal{R}(-\vartheta)$ are Euclidean isometries  egin{align} \skp{\xi^1}{\xi^1} &=  rac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))^2}{4\mu (\kappa^2-\mu)} +  rac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))^2}{4\mu^2 (\kappa^2-\mu)} 
otag \ &=  rac{\cos^2(\phi)(\kappa^4+4\mu) + \sin^2(\phi)(4\kappa^2-\kappa^4) - 4\kappa^2\kappa'\sin(\phi)\cos(\phi)}{4\mu^2 } 
otag \ &\;+ rac{ 4\kappa^2-4\mu - 4\kappa^3 \cos(\phi)+8\kappa\kappa'\sin(\phi)}{4\mu^2} 
otag \ &=  rac{(2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))^2}{4\mu^2} 
otag \ &\stackrel{\eqref{eq:b3a3_2}}{=} a_3^2\gamma_2^2 . \ \intertext{Similar computations yield $((\xi^1)^\perp:=(-\xi^1_2,\xi^1_1))$} \skp{\xi^1}{\xi^3} &=  rac{\kappa^2\kappa'\cos^2(\phi) - 2 \kappa^2\kappa'\sin^2(\phi) + (\kappa^4-4(\kappa')^2)\sin(\phi)\cos(\phi) }{4\mu^2} 
otag \ &\;+  rac{-2\kappa^3\sin(\phi) - 4\kappa\kappa'\cos(\phi) }{4\mu^2} 
otag \ &= -  rac{(\kappa^2\sin(\phi)+2\kappa'\cos(\phi)) (2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{4\mu^2 } 
otag \ &\stackrel{\eqref{eq:b3a3_1},\eqref{eq:b3a3_2}}{=} a_3(b_3-\gamma_1 a_3), \ \skp{(\xi^1)^\perp}{\xi^3} &=  rac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi)) (2\kappa'\sin(\phi)-\kappa^2\cos(\phi)) }{ 4\mu^{3/2}(\kappa^2-\mu)} 
otag \ &\;+  rac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))(\kappa^3\sin(\phi)+2\kappa\kappa'\cos(\phi)) }{4\mu^{3/2}(\kappa^2-\mu)} 
otag \ &=  rac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu^{3/2} (2-k^2)} 
otag \ &\stackrel{\eqref{eq:b3a3_2}}{=}  rac{a_3\gamma_2}{\sqrt\mu}. \end{align} This implies  egin{align*} a_1^2+a_2^2 \stackrel{\eqref{eq:a1a2b1b2_1}}{=}  rac{1}{\gamma_2^2}\skp{\xi^1}{\xi^1} \stackrel{\eqref{eq:formulas_scpr_xi_1}}{=} a_3^2. \end{align*} Hence, we find the formula for $a_3$ from \eqref{eq:a_1a_2a_3b_1b_2b_3} since $a_3$ is positive due to  egin{align*} a_3 \stackrel{\eqref{eq:b3a3_2}}{=}  rac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu \gamma_2} \geq  rac{2\kappa-\sqrt{(2\kappa')^2+\kappa^4}}{2\mu \gamma_2} \stackrel{\eqref{eq:ODE_kappa}}{=}  rac{\kappa-\sqrt{\kappa^2-\mu}}{\mu\gamma_2} > 0. \end{align*} Similarly we get  egin{align*} b_1a_1+b_2a_2 &\hspace{-3mm}\stackrel{\eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2}}{=}  rac{\gamma_1}{\gamma_2^2}\skp{\xi^1}{\xi^1} +  rac{1}{ \gamma_2}\skp{\xi^1}{\xi^3} \stackrel{\eqref{eq:formulas_scpr_xi_1},\eqref{eq:formulas_scpr_xi_2}}{=} \gamma_1a_3^2 + a_3(b_3-\gamma_1 a_3) = b_3a_3, \ -b_1a_2+b_2a_1 &\hspace{-3mm}\stackrel{\eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2}}{=}  rac{1}{\gamma_2}\skp{(\xi^1)^\perp}{\xi^3} \stackrel{\eqref{eq:formulas_scpr_xi_3}}{=}  rac{a_3}{\sqrt\mu}. \end{align*} Combining these equations we obtain the formulas for $b_1,b_2$ and \eqref{eq:a_1a_2a_3b_1b_2b_3} is proved. \medskip Now we prove the sufficiency of our conditions, so let $a_1,\ldots,b_3$ be given as in \eqref{eq:a_1a_2a_3b_1b_2b_3} we define $\gamma_1,\gamma_2$ by the formulas \eqref{eq:explicit_formula_orbitlike_1},\eqref{eq:explicit_formula_orbitlike_2}. Motivated by the formulas~\eqref{eq:b3a3_1},\eqref{eq:b3a3_2} derived in the ''only if''-part we define $\phi$ via  egin{equation} \vecII{\sin(\phi)}{\cos(\phi)} :=  rac{\mu a_3}{2(\kappa^2-\mu)}\matII{\kappa^2}{2\kappa'}{2\kappa'}{-\kappa^2} \vecII{\gamma_1- rac{b_3}{a_3}}{\gamma_2- rac{\kappa}{\mu a_3}}. \end{equation} We have to verify that such a definition makes sense by checking that the Euclidean norm of the vector on the right hand side is 1. We introduce the notation $$ aW:=a_1W_1+a_2W_2,\quad a^\perp W:=-a_2W_1+a_1W_2, \quad bW:= b_1W_1+b_2W_2 $$ so that we can use the following facts: $$ \gamma_1 \stackrel{\eqref{eq:explicit_formula_orbitlike_1}}{=}  rac{bW+b_3}{aW+a_3},\quad \gamma_2 \stackrel{\eqref{eq:explicit_formula_orbitlike_2}}{=}  rac{1}{\kappa(aW+a_3)},\quad b \stackrel{\eqref{eq:a_1a_2a_3b_1b_2b_3}}{=}  rac{b_3}{a_3} a +  rac{1}{\sqrt\mu a_3} a^\perp,\quad a_3bW-b_3 aW \stackrel{\eqref{eq:a_1a_2a_3b_1b_2b_3}}{=}  rac{1}{\sqrt\mu} a^\perp W. $$ This implies  egin{align*} & rac{\mu^2 a_3^2}{4(\kappa^2-\mu)^2} \Big( \Big( \kappa^2 ig(\gamma_1- rac{b_3}{a_3} ig)+2\kappa' ig(\gamma_2- rac{\kappa}{\mu a_3} ig)\Big)^2 + \Big( 2\kappa' ig(\gamma_1- rac{b_3}{a_3} ig)-2\kappa^2 ig(\gamma_2- rac{\kappa}{\mu a_3} ig) \Big)^2 \Big) \ &=  rac{\mu^2 a_3^2 (\kappa^4+4(\kappa')^2)}{4(\kappa^2-\mu)^2} \Big(  ig(\gamma_1- rac{b_3}{a_3} ig)^2+  ig(\gamma_2- rac{\kappa}{\mu a_3} ig)^2\Big) \ &=  rac{\mu^2 a_3^2}{\kappa^2-\mu} \Big(  ig(  rac{a_3bW-b_3aW}{a_3(aW+a_3)} ig)^2+  ig(  rac{-\kappa^2aW + (\mu-\kappa^2)a_3}{\mu\kappa a_3(aW+a_3)}  ig)^2\Big) \ &=  rac{ ig( \kappa\mu(a_3bW-b_3aW) ig)^2+  ig(-\kappa^2aW + (\mu-\kappa^2)a_3  ig)^2}{\kappa^2(\kappa^2-\mu)(aW+a_3)^2} \ &=  rac{ \kappa^2\mu(a^\perp W)^2 + \kappa^4(aW)^2 +2\kappa^2(\kappa^2-\mu)a_3aW+ (\kappa^2-\mu)^2a_3^2 }{\kappa^2(\kappa^2-\mu)(aW+a_3)^2} \ &=  rac{ \kappa^2\mu |a|^2|W|^2 + (\kappa^4-\kappa^2\mu)(aW)^2 +2\kappa^2(\kappa^2-\mu)a_3aW+ (\kappa^2-\mu)^2a_3^2 }{\kappa^2(\kappa^2-\mu)(aW+a_3)^2} \ &=  rac{(aW)^2 +2a_3aW+ a_3^2}{(aW+a_3)^2} \ &= 1. \end{align*} Here we have used $\kappa^2|a|^2|W|^2=(\kappa^2-\mu)a_3^2$, see \eqref{eq:a_1a_2a_3b_1b_2b_3} and Proposition~ef{prop:W1W2_orbitlike}~(i). It remains to check that $(\gamma_1,\gamma_2,\phi)$ satisfies the ODE~\eqref{eq:ODE_solution}. To this end, we first rewrite the formulas for $\sin(\phi),\cos(\phi)$ from \eqref{eq:formula_phi} in the following way:  egin{align*} \sin(\phi) &=  rac{\mu a_3}{2(\kappa^2-\mu)} \Big( \kappa^2 ig(  rac{bW+b_3}{aW+a_3}- rac{b_3}{a_3} ig) +2\kappa' ig(  rac{1}{\kappa(aW+a_3)}- rac{\kappa}{\mu a_3} ig) \Big) \ &=  rac{\mu a_3}{2(\kappa^2-\mu)} \Big(  rac{\kappa^2( bW a_3-aW b_3)}{a_3(aW+a_3)} +  rac{2\kappa'( \mu a_3-\kappa^2 (aW+a_3))}{\mu\kappa a_3(aW+a_3)} \Big) \ &=  rac{\mu a_3}{2(\kappa^2-\mu)} \Big(  rac{\kappa^2 a^\perp W}{\sqrt\mu a_3(aW+a_3)} +  rac{2\kappa'( (\mu-\kappa^2) a_3- \kappa^2 aW)}{\mu\kappa a_3(aW+a_3)} \Big) \ &=  rac{\sqrt\mu \kappa^3 a^\perp W - 2\kappa^2\kappa' aW - 2\kappa'(\kappa^2-\mu) a_3}{2\kappa(\kappa^2-\mu)(aW+a_3)}, \ \cos(\phi) &=  rac{2\sqrt\mu \kappa' a^\perp W + \kappa^3 aW + \kappa^2(\kappa^2-\mu)a_3}{2\kappa(\kappa^2-\mu)(aW+a_3)}. \end{align*} For the calculation of $\gamma_1',\gamma_2'$ we use the formula  egin{align*} W' =  rac{\mu\kappa'}{\kappa(\kappa^2-\mu)} W +  rac{\sqrt\mu \kappa^2}{2(\kappa^2-\mu)}W^\perp \end{align*} from Proposition~ef{prop:W1W2_orbitlike}~(ii),(iii). We obtain  egin{align*}  rac{\gamma_2'}{\gamma_2} &= -  rac{\kappa'}{\kappa} -  rac{aW'}{aW+a_3} \ &= -  rac{\kappa'}{\kappa} -  rac{2\mu\kappa' aW - \sqrt\mu\kappa^3 a^\perp W }{2\kappa(\kappa^2-\mu)(aW+a_3)} \ &=  rac{ \sqrt\mu \kappa^3 a^\perp W - 2\kappa^2\kappa' aW - 2\kappa'(\kappa^2-\mu)a_3}{2\kappa(\kappa^2-\mu)(aW+a_3)} \ &= \sin(\phi). \ \intertext{Similarly, $|a|^2=a_1^2+a_2^2=a_3^2$ implies}  rac{\gamma_1'}{\gamma_2} &= \kappa(aW+a_3) \Big(  rac{bW+b_3}{aW+a_3}\Big)' \ &= \kappa bW' -\kappa aW'  rac{bW+b_3}{aW+a_3} \ &= \kappa W'  ig( - rac{a^\perp W}{\sqrt\mu a_3(aW+a_3)} a +  rac{1}{\sqrt\mu a_3}a^\perp  ig) \ &=  rac{(2\sqrt\mu\kappa' W + \kappa^3 W^\perp) (- (a^\perp W) a + (aW+a_3)a^\perp)}{2a_3(aW+a_3)(\kappa^2-\mu)} \ &=  rac{\kappa^3 (a^\perp W)^2+\kappa^3 (aW)^2 + a_3(\kappa^3 aW + 2\sqrt\mu\kappa' a^\perp W)}{2a_3(aW+a_3)(\kappa^2-\mu)} \ &=  rac{\kappa^3 |a|^2|W|^2 + a_3(\kappa^3 aW + 2\sqrt\mu\kappa' a^\perp W)}{2a_3(aW+a_3)(\kappa^2-\mu)} \ &=  rac{a_3\kappa(\kappa^2-\mu) + \kappa^3 aW + 2\sqrt\mu\kappa' a^\perp W}{2(aW+a_3)(\kappa^2-\mu)} \ &= \cos(\phi). \end{align*} Here, once again we used $\kappa^3|a|^2|W|^2 = \kappa(\kappa^2-\mu)$. So we see that the equations for $\gamma_1,\gamma_2$ from \eqref{eq:ODE_solution} are satisfied and it remains to verify the ODE for $\phi$. Having defined $\phi$ in \eqref{eq:formula_phi} in such a way that \eqref{eq:b3a3_1},\eqref{eq:b3a3_2} holds, we may differentiate these equations in order to derive the formula for $\phi'$. Differentiating \eqref{eq:b3a3_1} and using $\gamma_1'=\gamma_2\cos(\phi)$ as well as \eqref{eq:b3a3_2} we find  egin{align*} 2\kappa'(\kappa-\phi')\sin(\phi) + (\kappa^2\phi'+2\kappa-\kappa^3)\cos(\phi) = 2\kappa\cos(\phi)+2\kappa'\sin(\phi)\cos(\phi)-\kappa^2\cos^2(\phi) \end{align*} Differentiating \eqref{eq:b3a3_2} and using $\gamma_2'=\gamma_2\sin(\phi)$ as well as \eqref{eq:b3a3_2} we get  egin{align*} -2\kappa'(\kappa-\phi')\cos(\phi) + (\kappa^2\phi'+2\kappa-\kappa^3)\sin(\phi) = -2\kappa'\cos(\phi)+2\kappa \sin(\phi) -\kappa^2\sin(\phi)\cos(\phi) \end{align*} Multiplying the first equation with $\sin(\phi)$, the second with $-\cos(\phi)$ and adding up the resulting equations we arrive at $2\kappa'(\kappa-\phi')=2\kappa'\cos(\phi)$ and thus $\phi'+\cos(\phi)=\kappa$. So $(\gamma_1,\gamma_2,\phi)$ is a solution to the the ODE \eqref{eq:ODE_solution} and hence an orbitlike elastica, which is all we had to prove.

Writing $\skp{\cdot}{\cdot}$ for the standard inner product in $\mathbb{R}^2$ we get from $(\kappa')^2=\kappa^2- rac{\kappa^4}{4}-\mu$ and the fact that the rotation matrices $\mathcal{R}(-\vartheta)$ are Euclidean isometries  egin{align} \skp{\xi^1}{\xi^1} &=  rac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))^2}{4\mu (\kappa^2-\mu)} +  rac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))^2}{4\mu^2 (\kappa^2-\mu)} 
otag \ &=  rac{\cos^2(\phi)(\kappa^4+4\mu) + \sin^2(\phi)(4\kappa^2-\kappa^4) - 4\kappa^2\kappa'\sin(\phi)\cos(\phi)}{4\mu^2 } 
otag \ &\;+ rac{ 4\kappa^2-4\mu - 4\kappa^3 \cos(\phi)+8\kappa\kappa'\sin(\phi)}{4\mu^2} 
otag \ &=  rac{(2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))^2}{4\mu^2} 
otag \ &\stackrel{\eqref{eq:b3a3_2}}{=} a_3^2\gamma_2^2 . \ \intertext{Similar computations yield $((\xi^1)^\perp:=(-\xi^1_2,\xi^1_1))$} \skp{\xi^1}{\xi^3} &=  rac{\kappa^2\kappa'\cos^2(\phi) - 2 \kappa^2\kappa'\sin^2(\phi) + (\kappa^4-4(\kappa')^2)\sin(\phi)\cos(\phi) }{4\mu^2} 
otag \ &\;+  rac{-2\kappa^3\sin(\phi) - 4\kappa\kappa'\cos(\phi) }{4\mu^2} 
otag \ &= -  rac{(\kappa^2\sin(\phi)+2\kappa'\cos(\phi)) (2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{4\mu^2 } 
otag \ &\stackrel{\eqref{eq:b3a3_1},\eqref{eq:b3a3_2}}{=} a_3(b_3-\gamma_1 a_3), \ \skp{(\xi^1)^\perp}{\xi^3} &=  rac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi)) (2\kappa'\sin(\phi)-\kappa^2\cos(\phi)) }{ 4\mu^{3/2}(\kappa^2-\mu)} 
otag \ &\;+  rac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))(\kappa^3\sin(\phi)+2\kappa\kappa'\cos(\phi)) }{4\mu^{3/2}(\kappa^2-\mu)} 
otag \ &=  rac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu^{3/2} (2-k^2)} 
otag \ &\stackrel{\eqref{eq:b3a3_2}}{=}  rac{a_3\gamma_2}{\sqrt\mu}. \end{align}

\skp{\xi^1}{\xi^1} &=  rac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))^2}{4\mu (\kappa^2-\mu)} +  rac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))^2}{4\mu^2 (\kappa^2-\mu)} 
otag \ &=  rac{\cos^2(\phi)(\kappa^4+4\mu) + \sin^2(\phi)(4\kappa^2-\kappa^4) - 4\kappa^2\kappa'\sin(\phi)\cos(\phi)}{4\mu^2 } 
otag \ &\;+ rac{ 4\kappa^2-4\mu - 4\kappa^3 \cos(\phi)+8\kappa\kappa'\sin(\phi)}{4\mu^2} 
otag \ &=  rac{(2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))^2}{4\mu^2} 
otag \ &\stackrel{\eqref{eq:b3a3_2}}{=} a_3^2\gamma_2^2 . \ \intertext{Similar computations yield $((\xi^1)^\perp:=(-\xi^1_2,\xi^1_1))$} \skp{\xi^1}{\xi^3} &=  rac{\kappa^2\kappa'\cos^2(\phi) - 2 \kappa^2\kappa'\sin^2(\phi) + (\kappa^4-4(\kappa')^2)\sin(\phi)\cos(\phi) }{4\mu^2} 
otag \ &\;+  rac{-2\kappa^3\sin(\phi) - 4\kappa\kappa'\cos(\phi) }{4\mu^2} 
otag \ &= -  rac{(\kappa^2\sin(\phi)+2\kappa'\cos(\phi)) (2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{4\mu^2 } 
otag \ &\stackrel{\eqref{eq:b3a3_1},\eqref{eq:b3a3_2}}{=} a_3(b_3-\gamma_1 a_3), \ \skp{(\xi^1)^\perp}{\xi^3} &=  rac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi)) (2\kappa'\sin(\phi)-\kappa^2\cos(\phi)) }{ 4\mu^{3/2}(\kappa^2-\mu)} 
otag \ &\;+  rac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))(\kappa^3\sin(\phi)+2\kappa\kappa'\cos(\phi)) }{4\mu^{3/2}(\kappa^2-\mu)} 
otag \ &=  rac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu^{3/2} (2-k^2)} 
otag \ &\stackrel{\eqref{eq:b3a3_2}}{=}  rac{a_3\gamma_2}{\sqrt\mu}.
